// ── Binary ↔ Decimal conversions ──────────────────────────────

// Built-in shortcuts
console.log((42).toString(2));      // "101010"   decimal → binary string
console.log(parseInt('101010', 2)); // 42         binary string → decimal
console.log(0b101010);              // 42         binary literal
console.log(0x2A);                  // 42         hex literal

// Manual place-value expansion — makes the math visible
function fromBinary(bits) {
  return [...bits].reverse().reduce((sum, bit, i) => {
    return sum + Number(bit) * (2 ** i);
  }, 0);
}
console.log(fromBinary('1011'));   // 11   (8+0+2+1)
console.log(fromBinary('1111'));   // 15   (8+4+2+1)

// Division-by-2 method — see the algorithm clearly
function toBinaryByDivision(n) {
  if (n === 0) return '0';
  let bits = [];
  while (n > 0) {
    bits.push(n & 1);  // remainder when dividing by 2
    n >>= 1;           // integer divide by 2
  }
  return bits.reverse().join('');
}
console.log(toBinaryByDivision(42)); // "101010"
console.log(toBinaryByDivision(255)); // "11111111"
